    try:
        # initialize grid
        grid = [[0]*(N+1) for _ in range(N+1)]
        for x,y,val in grid_values:
            if x==0 and y==0 and val==0:
                break
            if 1 <= x <= N and 1 <= y <= N:
                grid[x][y] = val
        # DP
        NEG = -10**15
        dp_prev = [[NEG]*(N+1) for _ in range(N+1)]
        dp_prev[1][1] = grid[1][1]
        for t in range(3, 2*N+1):
            dp_curr = [[NEG]*(N+1) for _ in range(N+1)]
            i_min = max(1, t - N)
            i_max = min(N, t - 1)
            for i1 in range(i_min, i_max+1):
                j1 = t - i1
                if j1 < 1 or j1 > N:
                    continue
                for i2 in range(i_min, i_max+1):
                    j2 = t - i2
                    if j2 < 1 or j2 > N:
                        continue
                    best = NEG
                    for di1 in (-1, 0):
                        for di2 in (-1, 0):
                            pi1 = i1 + di1
                            pi2 = i2 + di2
                            if pi1 < 1 or pi2 < 1:
                                continue
                            p_prev = dp_prev[pi1][pi2]
                            if p_prev > best:
                                best = p_prev
                    if best == NEG:
                        continue
                    add = grid[i1][j1]
                    if i1 != i2 or j1 != j2:
                        add += grid[i2][j2]
                    dp_curr[i1][i2] = best + add
            dp_prev = dp_curr
        result = dp_prev[N][N]
        return result if result != NEG else 0
    except Exception:
        return 0

