def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize placement of aisles in a classroom to minimize chatting.

    Parameters:
    M (int): number of rows.
    N (int): number of columns.
    K (int): number of horizontal aisles to add.
    L (int): number of vertical aisles to add.
    D (int): number of chatting pairs.
    chatting_pairs (list): list of tuples (Xi, Yi, Pi, Qi).

    Returns:
    (str, str): Two space-separated strings:
        - horizontal aisle indices (1-based, between rows).
        - vertical aisle indices (1-based, between columns).
    """
    # Basic input validation
    try:
        if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0 or not isinstance(chatting_pairs, list):
            return ("", "")
    except Exception:
        return ("", "")

    # Possible aisle positions
    hori_positions = range(1, M)  # aisle between row r and r+1
    vert_positions = range(1, N)  # aisle between col c and c+1

    # Count separation for each horizontal aisle
    hori_counts = {r: 0 for r in hori_positions}
    vert_counts = {c: 0 for c in vert_positions}

    for idx, pair in enumerate(chatting_pairs):
        if not (isinstance(pair, (list, tuple)) and len(pair) == 4):
            continue  # skip malformed pair
        xi, yi, pi, qi = pair
        min_row, max_row = min(xi, pi), max(xi, pi)
        min_col, max_col = min(yi, qi), max(yi, qi)
        # Horizontal aisles
        for r in hori_positions:
            if min_row < r < max_row:
                hori_counts[r] += 1
        # Vertical aisles
        for c in vert_positions:
            if min_col < c < max_col:
                vert_counts[c] += 1

    # Select top K horizontal aisles
    sorted_hori = sorted(hori_counts.items(), key=lambda x: (-x[1], x[0]))
    chosen_hori = [str(r) for r, _ in sorted_hori[:K]]
    horiz_str = " ".join(chosen_hori)

    # Select top L vertical aisles
    sorted_vert = sorted(vert_counts.items(), key=lambda x: (-x[1], x[0]))
    chosen_vert = [str(c) for c, _ in sorted_vert[:L]]
    vert_str = " ".join(chosen_vert)

    return (horiz_str, vert_str)

def count_passing_ways(n: int, m: int) -> int:
    """
    Counts the number of distinct passing ways that result in the ball
    returning to the starting student after 'm' passes on a circle
    of 'n' students where each pass is to an adjacent student.

    Args:
        n (int): Number of students standing in a circle.
        m (int): Number of times the ball is passed.

    Returns:
        int: The number of distinct passing sequences that return to the start.
    """
    if not isinstance(n, int) or not isinstance(m, int):
        raise TypeError("Both 'n' and 'm' must be integers.")
    if n <= 0:
        raise ValueError("'n' must be a positive integer.")
    if m < 0:
        raise ValueError("'m' must be a non-negative integer.")

    try:
        from math import comb
    except Exception:  # Fallback for older Python versions
        from math import factorial

        def comb(n_val, k_val):
            if k_val < 0 or k_val > n_val:
                return 0
            return factorial(n_val) // (factorial(k_val) * factorial(n_val - k_val))

    total = 0
    for k in range(m + 1):
        if (2 * k - m) % n == 0:
            total += comb(m, k)
    return total

