def largest_prime_factor(n: int) -> int:
    """
    Find the largest prime factor of a given positive integer that is the product of two distinct primes.
    """
    if not isinstance(n, int) or n <= 1:
        raise ValueError("n must be a positive integer greater than 1")
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1 if i == 2 else 2
    return n

def count_partitions(n,k,x):
