def remaining_trees_after_clearing(l: int, areas: list[tuple[int, int]]) -> int:
    if l <= 0:
        return 0
    # Normalize intervals to [start, end) within the road length
    intervals = []
    for s, e in areas:
        start = max(0, s)
        end = min(l, e)
        if start < end:          # Valid interval
            intervals.append((start, end))
    if not intervals:
        return l
    # Merge overlapping intervals
    intervals.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = intervals[0]
    for st, en in intervals[1:]:
        if st <= cur_end:            # Overlaps or touches
            if en > cur_end:
                cur_end = en
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = st, en
    merged.append((cur_start, cur_end))
    # Total cleared length
    cleared = sum(end - start for start, end in merged)
    remaining = l - cleared
    return max(0, remaining)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """Calculate the maximum total value of herbs that can be picked within a given time limit."""
    try:
        if not isinstance(T, int) or not isinstance(M, int) or T < 0 or M < 0:
            return 0
        if not herbs or M == 0:
            return 0
        # Separate zero‑time herbs because they can always be taken once
        zero_time_value = 0
        real_herbs: List[Tuple[int, int]] = []
        for t, v in herbs:
            if not isinstance(t, int) or not isinstance(v, int):
                continue
            if t <= 0:
                if t == 0 and v > 0:
                    zero_time_value += v
            else:
                real_herbs.append((t, v))
        if not real_herbs or T == 0:
            return zero_time_value
        dp = [0] * (T + 1)
        for time, value in real_herbs:
            for cap in range(T, time - 1, -1):
                new_val = dp[cap - time] + value
                if new_val > dp[cap]:
                    dp[cap] = new_val
        return dp[T] + zero_time_value
    except Exception:
        return 0

def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    """
    Calculate the minimum remaining space in a box after attempting to pack a subset of items.

    Args:
        V (int): Total capacity of the box.
        n (int): Number of items to consider.
        volumes (List[int]): Volumes of the items.

    Returns:
        int: Minimum remaining space after packing.

    Raises:
        ValueError: If V or n is negative or if volumes contains non-integer values.
        TypeError: If arguments are of incorrect types.
    """
    # Input validation
    if not isinstance(V, int) or not isinstance(n, int):
        raise TypeError("V and n must be integers.")
    if V < 0:
        raise ValueError("Box capacity V must be non-negative.")
    if n < 0:
        raise ValueError("Number of items n must be non-negative.")
    if not isinstance(volumes, list):
        raise TypeError("volumes must be a list.")
    for v in volumes:
        if not isinstance(v, int):
            raise TypeError("Each volume must be an integer.")
        if v < 0:
            raise ValueError("Volume values must be non-negative.")

    # Limit volumes to the first n items
    items = volumes[:n]

    # DP array to track achievable sums
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in items:
        # Skip items larger than the box capacity
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True

    # Find the maximum achievable volume not exceeding V
    max_used = 0
    for cap in range(V, -1, -1):
        if dp[cap]:
            max_used = cap
            break

    return V - max_used.

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if heights is None:
        return 0
    if not isinstance(heights, list):
        raise TypeError("heights must be a list of integers")
    n = len(heights)
    if n == 0:
        return 0
    try:
        heights = [int(h) for h in heights]
    except Exception as exc:
        raise TypeError("heights must contain integer values") from exc

    # Compute LIS (strictly increasing) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS (strictly decreasing) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest Bitonic Subsequence length
    max_len = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    # Minimum removals
    return n - max_len

